    "rarity": "common",
    "edition": "remaster",
    "publication": "Pathfinder Impossible Magic",
    "path": "packs/pf2e/feats/class/summoner/level-8/constricting-hold.json",
    "sourceUrl": "https://github.com/foundryvtt/pf2e/blob/581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb/packs/pf2e/feats/class/summoner/level-8/constricting-hold.json",
