    "id": "3xKOqBaPApgsnRtB",
    "name": "Dance of the Tiger",
    "img": "icons/sundries/books/book-red-exclamation.webp",
    "slug": "dance-of-the-tiger",
    "level": 9,
    "actionType": "action",
    "actions": 1,
