    "id": "PLix02TPp7VaClka",
    "name": "Idol Threat",
    "img": "icons/sundries/books/book-red-exclamation.webp",
    "slug": "idol-threat",
    "level": 13,
    "actionType": "action",
    "actions": 1,
    "activation": "action",
