    "path": "packs/pf2e/feats/archetype/five-breath-vanguard/protective-cycle.json",
    "sourceUrl": "https://github.com/foundryvtt/pf2e/blob/581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb/packs/pf2e/feats/archetype/five-breath-vanguard/protective-cycle.json",
