    "id": "zJsu5JQGGOpyT6Xk",
    "name": "Stages of Fate",
    "img": "icons/sundries/books/book-red-exclamation.webp",
    "slug": "stages-of-fate",
    "level": 8,
    "actionType": "action",
    "actions": 2,
    "activation": "action",
