    "theme": "light",
    "motif": "elementTarget",
    "subject": "targets",
    "quality": "themed",
    "authored": false,
    "rationale": "Sleek wing reflection sweeps narrow glare toward foe eyes. No source flight despite wings.",
    "evidence": [
      "catch the light across your wings"
    ],
    "descriptionChars": 416,
