    "id": "F8V4dN91JmHIOQCv",
    "name": "Topple The Titans",
    "img": "icons/sundries/books/book-red-exclamation.webp",
    "slug": "topple-the-titans",
    "level": 4,
    "actionType": "action",
    "actions": 1,
    "activation": "action",
